/**
 * 雇用保険の届書の電子申請用ファイル（ハローワークに出す CSV形式届書ファイル）の形
 *
 * 厚生労働省 職業安定局「磁気媒体届書作成仕様書（光ディスク等仕様書）／ＣＳＶ形式届書作成仕様書（電子申請）（雇用保険適用関係届書）」令和5年11月（第14.00版）
 * と「雇用保険事務手続きの手引き【第２編】」から、scripts/import_koyo_format.py で作ったファイルです。手で直さないでください。
 * 作り方と入手元は koyo-format/README.md
 */

/** 項目の決まり（種別・文字数。only は書ける文字数を並べたもの。alt はカナなどで書くときの決まり。eras は書ける元号） */
export interface KoyoField {
  name: string;
  kinds: string[];
  min: number;
  max: number;
  only?: number[];
  alt?: { name: string; kinds: string[]; min: number; max: number; only?: number[] };
  eras?: string[];
}

export type KoyoForm = "shutoku" | "soshitsu" | "rishoku" | "tenkin" | "bango";

